type Paths<T, Prev extends string = ""> = {
  [K in keyof T]: T[K] extends object
    ? Paths<T[K], `${Prev}${K & string}.`>
    : `${Prev}${K & string}`;
}[keyof T];

export type typeLanguagesKeys = Paths<typeLanguages>;
export type typeLanguagesServerKeys = Paths<typeLanguagesServer>;
